import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.DatePicker
import androidx.compose.material3.DatePickerDialog
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.material3.rememberDatePickerState
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import java.util.Date

@Composable
fun CampsiteAvailabilityView(
    onSave: (Date, Date) -> Unit,
    onBack: () -> Unit
) {
    var startDate by remember { mutableStateOf<Long?>(null) }
    var endDate by remember { mutableStateOf<Long?>(null) }
    var selectingStart by remember { mutableStateOf(true) }

    val dateState = rememberDatePickerState()

    DatePickerDialog(
        onDismissRequest = onBack,
        confirmButton = {
            TextButton(
                enabled = dateState.selectedDateMillis != null,
                onClick = {
                    val selectedDate = dateState.selectedDateMillis!!

                    if (selectingStart) {
                        startDate = selectedDate
                        selectingStart = false
                        dateState.selectedDateMillis = null
                    } else {
                        if (startDate != null && selectedDate >= startDate!!) {
                            endDate = selectedDate
                            onSave(Date(startDate!!), Date(endDate!!))
                        }
                    }
                }
            ) {
                Text(if (selectingStart) "NEXT" else "SAVE")
            }
        },
        dismissButton = {
            TextButton(
                onClick = {
                    if (!selectingStart) {
                        selectingStart = true
                        dateState.selectedDateMillis = startDate
                    } else {
                        onBack()
                    }
                }
            ) {
                Text("BACK")
            }
        }
    ) {
        Column(modifier = Modifier.fillMaxWidth()) {
            Text(
                text = if (selectingStart) {
                    "Select Start Date"
                } else {
                    "Select End Date"
                },
                modifier = Modifier.padding(16.dp)
            )

            DatePicker(
                state = dateState,
                showModeToggle = false
            )
        }
    }
}
